      "citationCount": 0,
      "referenceCount": 0,
      "url": "https://www.semanticscholar.org/paper/2e459926f9c33a7f9508790b2b597aede07c069b"
    },
    {
      "paperId": "7408c5ebe3a98797465530c65b8b5b470a94a67a",
      "title": "Large-Area Farmland Semantic Segmentation for Crop Health and Intrusion Monitoring via Multi-Agent Cooperative Unmanned-Aerial-Vehicles",
      "abstract": null,
      "authors": [
        {
